import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"CoreLib Actions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/skills/corelib-actions.md","filePath":"en/modules/skills/corelib-actions.md","lastUpdated":0}`),a={name:`en/modules/skills/corelib-actions.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="corelib-actions" tabindex="-1">CoreLib Actions <a class="header-anchor" href="#corelib-actions" aria-label="Permalink to “CoreLib Actions”">​</a></h1><p>When EmakiSkills is enabled, it adds skill cast, level, slot, cooldown, and manual-unlock stages to the CoreLib action registry. Use them in other modules&#39; rewards, trigger follow-up effects, or CoreLib pipeline templates.</p><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>This page documents only the stages registered by EmakiSkills. EmakiSkills&#39; own native skill script actions are documented in <a href="./script.html">Native Script System</a>, and CoreLib built-in stages in <a href="./../corelib/actions.html">CoreLib Actions</a>.</p></div><h2 id="stage-id-reference" tabindex="-1">Stage ID reference <a class="header-anchor" href="#stage-id-reference" aria-label="Permalink to “Stage ID reference”">​</a></h2><p>All twelve stages declare <code>REQUIRED_ENTITY</code>. Apart from <code>cast_skill</code> and <code>cast_mythic_skill</code>, they accept only player targets and skip anything else.</p><table tabindex="0"><thead><tr><th>Stage ID</th><th>Purpose</th></tr></thead><tbody><tr><td><code>cast_skill</code></td><td>Casts an EmakiSkills skill with the target as the caster.</td></tr><tr><td><code>cast_mythic_skill</code></td><td>Casts a MythicMobs skill with the target as the caster.</td></tr><tr><td><code>skill_set_level</code></td><td>Sets one of the target&#39;s skill levels directly.</td></tr><tr><td><code>skill_upgrade</code></td><td>Upgrades one of the target&#39;s skills through the upgrade service.</td></tr><tr><td><code>skill_equip</code></td><td>Equips a skill into one of the target&#39;s skill slots.</td></tr><tr><td><code>skill_unequip</code></td><td>Clears one of the target&#39;s skill slots.</td></tr><tr><td><code>skill_bind</code></td><td>Binds a trigger to one of the target&#39;s skill slots.</td></tr><tr><td><code>skill_cooldown_clear</code></td><td>Clears one or all of the target&#39;s skill cooldowns.</td></tr><tr><td><code>skill_cooldown_set</code></td><td>Sets one of the target&#39;s skill cooldowns.</td></tr><tr><td><code>skill_learn</code></td><td>Unlocks a skill through the manual skill source.</td></tr><tr><td><code>skill_forget</code></td><td>Removes one manually unlocked skill.</td></tr><tr><td><code>skill_forget_all</code></td><td>Removes all manually unlocked skills.</td></tr></tbody></table><p>Old IDs map as follows: <code>castskill</code> and <code>skill.cast</code> are no longer registered, <code>skill_setlevel</code> is now <code>skill_set_level</code>, and <code>skill_clearcooldown</code> / <code>skill_setcooldown</code> are now <code>skill_cooldown_clear</code> / <code>skill_cooldown_set</code>. The IDs of <code>skill_upgrade</code>, <code>skill_equip</code>, <code>skill_unequip</code>, <code>skill_bind</code>, <code>skill_learn</code>, <code>skill_forget</code>, and <code>skill_forget_all</code> are unchanged.</p><p>Which entity is affected comes from the source: use <code>self</code> for the caster, or <code>player_by_name</code> for a named player.</p><h2 id="cast-skill" tabindex="-1">cast_skill <a class="header-anchor" href="#cast-skill" aria-label="Permalink to “cast_skill”">​</a></h2><p>Casts an EmakiSkills skill with the target as the caster.</p><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p><strong>Breaking change.</strong> The <code>skill</code> parameter takes an <strong>EmakiSkills skill id</strong>, not a MythicMobs skill id. Configuration that used to pass a MythicMobs skill name here must move to <code>cast_mythic_skill</code>.</p></div><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>skill</code></td><td>STRING</td><td>Yes</td><td>—</td><td>EmakiSkills skill id.</td></tr><tr><td><code>bypass_cooldown</code></td><td>BOOLEAN</td><td>No</td><td><code>false</code></td><td>Skips the per-skill and global cooldown checks.</td></tr><tr><td><code>bypass_resource_check</code></td><td>BOOLEAN</td><td>No</td><td><code>false</code></td><td>Casts even when the caster cannot afford it.</td></tr><tr><td><code>consume_resource</code></td><td>BOOLEAN</td><td>No</td><td><code>true</code></td><td>Whether a successful cast bills its resource costs.</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | cast_skill skill=fireball&#39;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # Admin testing: no cooldown, no resource cost</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | cast_skill skill=fireball bypass_cooldown=true consume_resource=false&#39;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # One free cast even when resources are short</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | cast_skill skill=heal bypass_resource_check=true consume_resource=false&#39;</span></span></code></pre></div><p>This stage goes through EmakiSkills&#39; own cast flow, so cooldowns, resource costs, cast conditions, and the pre/post cast events all apply.</p><h3 id="player-and-non-player-casters" tabindex="-1">Player and non-player casters <a class="header-anchor" href="#player-and-non-player-casters" aria-label="Permalink to “Player and non-player casters”">​</a></h3><p>The two paths behave differently, because a skill profile only exists for players:</p><ul><li><strong>Player caster</strong>: the full cast flow, with all three switches above in effect.</li><li><strong>Any other entity</strong>: only the skill&#39;s <code>mythicSkill</code> component is cast. A mob has no profile, so there is no cooldown to read and no resource pool to bill; the three switches are inert on this path, and a script-only skill (one with no <code>mythicSkill</code> configured) is refused rather than silently doing nothing.</li></ul><h3 id="how-the-outcome-is-decided" tabindex="-1">How the outcome is decided <a class="header-anchor" href="#how-the-outcome-is-decided" aria-label="Permalink to “How the outcome is decided”">​</a></h3><p>The cast flow is asynchronous but the stage must answer synchronously, so it inspects the settled state once without waiting: a cast that already failed by the time the call returns was stopped at a synchronous gate (cooldown, resource, wrong activation type), and that is a result the pipeline can branch on. A cast still in progress is reported as success, with any later failure going to the debug log only. This matches the tradeoff <code>start_task</code> makes: the stage guarantees the cast was accepted, not that it finished.</p><p>A blank <code>skill</code> or an unknown skill id fails with <code>INVALID_CONFIG</code>.</p><h2 id="cast-mythic-skill" tabindex="-1">cast_mythic_skill <a class="header-anchor" href="#cast-mythic-skill" aria-label="Permalink to “cast_mythic_skill”">​</a></h2><p>Casts a MythicMobs skill with the target as the caster. This stage moved from CoreLib to EmakiSkills in this round; its registered category is <code>integration</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>skill</code></td><td>STRING</td><td>Yes</td><td>—</td><td>MythicMobs skill id.</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | cast_mythic_skill skill=FireballSkill&#39;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # Make the entity under the crosshair cast it</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;looking_at range=20 | cast_mythic_skill skill=ExplodeSkill&#39;</span></span></code></pre></div><p>Any entity can be the caster, which is why this stage is separate from <code>cast_skill</code>. MythicMobs is an optional dependency: when it is absent or the bridge fails to initialise, the stage fails with <code>OWNER_DISABLED</code> instead of taking the pipeline down. The <code>skill</code> value is not id-normalised; it is passed through exactly as MythicMobs spells it.</p><h2 id="skill-levels" tabindex="-1">Skill levels <a class="header-anchor" href="#skill-levels" aria-label="Permalink to “Skill levels”">​</a></h2><h3 id="skill-set-level" tabindex="-1">skill_set_level <a class="header-anchor" href="#skill-set-level" aria-label="Permalink to “skill_set_level”">​</a></h3><p>Writes the level directly, ignoring upgrade costs and success rolls.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>skill</code></td><td>STRING</td><td>Yes</td><td>—</td><td>Skill id.</td></tr><tr><td><code>level</code></td><td>INTEGER</td><td>Yes</td><td>—</td><td>Target level.</td></tr></tbody></table><h3 id="skill-upgrade" tabindex="-1">skill_upgrade <a class="header-anchor" href="#skill-upgrade" aria-label="Permalink to “skill_upgrade”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>skill</code></td><td>STRING</td><td>Yes</td><td>—</td><td>Skill id.</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | skill_set_level skill=fireball level=3&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | skill_upgrade skill=fireball&#39;</span></span></code></pre></div><p><code>skill_upgrade</code> goes through EmakiSkills&#39; upgrade service, so upgrade materials, economy costs, success rates, and upgrade actions all still apply. An unknown skill id fails with <code>INVALID_CONFIG</code>.</p><h2 id="skill-slots" tabindex="-1">Skill slots <a class="header-anchor" href="#skill-slots" aria-label="Permalink to “Skill slots”">​</a></h2><table tabindex="0"><thead><tr><th>Stage ID</th><th>Parameters</th><th>Description</th></tr></thead><tbody><tr><td><code>skill_equip</code></td><td><code>slot</code> (INTEGER, required), <code>skill</code> (STRING, required)</td><td>Equips a skill into the given slot.</td></tr><tr><td><code>skill_unequip</code></td><td><code>slot</code> (INTEGER, required)</td><td>Clears the given slot.</td></tr><tr><td><code>skill_bind</code></td><td><code>slot</code> (INTEGER, required), <code>trigger</code> (STRING, required)</td><td>Binds a trigger to the given slot.</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | skill_equip slot=0 skill=fireball&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | skill_bind slot=0 trigger=right_click&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | skill_unequip slot=0&#39;</span></span></code></pre></div><p>Slot validation stays entirely inside <code>PlayerSkillStateService</code>, which owns the unlocked-skill set, the trigger conflict table, and the slot-change event. An unreadable <code>slot</code> falls back to <code>-1</code>, which the state service rejects, so a bad value fails loudly instead of hitting slot 0.</p><h2 id="cooldowns" tabindex="-1">Cooldowns <a class="header-anchor" href="#cooldowns" aria-label="Permalink to “Cooldowns”">​</a></h2><h3 id="skill-cooldown-clear" tabindex="-1">skill_cooldown_clear <a class="header-anchor" href="#skill-cooldown-clear" aria-label="Permalink to “skill_cooldown_clear”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>skill</code></td><td>STRING</td><td>No</td><td><code>&quot;&quot;</code></td><td>Skill id. Empty clears every cooldown and cast delay.</td></tr></tbody></table><h3 id="skill-cooldown-set" tabindex="-1">skill_cooldown_set <a class="header-anchor" href="#skill-cooldown-set" aria-label="Permalink to “skill_cooldown_set”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>skill</code></td><td>STRING</td><td>Yes</td><td>—</td><td>Skill id.</td></tr><tr><td><code>duration_ticks</code></td><td>TIME</td><td>Yes</td><td>—</td><td>Cooldown duration. Zero or less removes that skill&#39;s cooldown.</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | skill_cooldown_set skill=fireball duration_ticks=5s&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | skill_cooldown_clear skill=fireball&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | skill_cooldown_clear&#39;</span></span></code></pre></div><h2 id="manual-unlocks" tabindex="-1">Manual unlocks <a class="header-anchor" href="#manual-unlocks" aria-label="Permalink to “Manual unlocks”">​</a></h2><p>The manual skill source is written into the player&#39;s skill profile and shows as &quot;manually unlocked&quot; in the GUI. After a skill is forgotten, EmakiSkills revalidates and cleans up invalid slot bindings.</p><table tabindex="0"><thead><tr><th>Stage ID</th><th>Parameters</th><th>Description</th></tr></thead><tbody><tr><td><code>skill_learn</code></td><td><code>skill</code> (STRING, required)</td><td>Adds the skill to the player&#39;s manual source.</td></tr><tr><td><code>skill_forget</code></td><td><code>skill</code> (STRING, required)</td><td>Removes one manually unlocked skill.</td></tr><tr><td><code>skill_forget_all</code></td><td>none</td><td>Removes all manually unlocked skills.</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | skill_learn skill=fireball&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | skill_forget skill=fireball&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | skill_forget_all&#39;</span></span></code></pre></div><p>These three stages only touch the manual source. Skills granted by equipment or other sources are collected elsewhere and cannot be forgotten through them.</p><p><code>skill_learn</code> on an already unlocked skill is skipped rather than failed: the pipeline&#39;s intent is already satisfied.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li><code>cast_skill</code> and <code>cast_mythic_skill</code> accept any entity as the caster; the other ten stages accept only player targets.</li><li><code>cast_mythic_skill</code> requires MythicMobs to be installed and enabled, with the skill named by <code>skill</code> present.</li><li>Skill ids are normalised (case and separators) before use; MythicMobs skill ids are not.</li><li>When the relevant service is not ready, the stage fails with <code>MISSING_CONTEXT</code> rather than skipping silently.</li></ul>`,51)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};